Rules.InvariantScript:
With(
    {
        _peak: First(
            SortByColumns(
                colSkylineWeeks,
                If(
                    varSelectedSkylineMode = "WORKLOAD",
                    "WorkloadTotal",
                    "SubsystemsCount"
                ),
                SortOrder.Descending
            )
        )
    },
    If(
        IsBlank(_peak.WeekEnding),
        "--",
        Text(_peak.WeekEnding, "dd-mmm-yyyy")
    )
)

With(
    {
        _peak: First(
            SortByColumns(
                colSkylineWeeks,
                If(
                    varSelectedSkylineMode = "WORKLOAD",
                    "WorkloadTotal",
                    "SubsystemsCount"
                ),
                SortOrder.Descending
            )
        )
    },
    If(
        IsBlank(_peak.WeekEnding),
        "",
        Text(_peak.SubsystemsCount) & " Subsystems"
    )
)

Set(varSelectedSkylineWeek, ThisItem.WeekEnding);
ClearCollect(
    colSkylineSelectedWeek,
    SortByColumns(
        Filter(colSkylineRaw, WeekEnding = ThisItem.WeekEnding),
        "WorkloadScore",
        SortOrder.Descending
    )
)

With(
    {
        _max: Max(
            colSkylineWeeks,
            If(varSelectedSkylineMode = "WORKLOAD", WorkloadTotal, SubsystemsCount)
        ),
        _value: If(varSelectedSkylineMode = "WORKLOAD", ThisItem.WorkloadTotal, ThisItem.SubsystemsCount),
        _totalCount: Max(1, ThisItem.SubsystemsCount)
    },
    If(
        _max <= 0 || _value <= 0,
        0,
        Max(4, ((_value / _max) * 150) * (ThisItem.OnTrackCount / _totalCount))
    )
)

With(
    {
        _max: Max(
            colSkylineWeeks,
            If(varSelectedSkylineMode = "WORKLOAD", WorkloadTotal, SubsystemsCount)
        ),
        _value: If(varSelectedSkylineMode = "WORKLOAD", ThisItem.WorkloadTotal, ThisItem.SubsystemsCount),
        _totalCount: Max(1, ThisItem.SubsystemsCount)
    },
    If(
        _max <= 0 || _value <= 0,
        0,
        Max(0, ((_value / _max) * 150) * (ThisItem.AttentionCount / _totalCount))
    )
)

With(
    {
        _max: Max(
            colSkylineWeeks,
            If(varSelectedSkylineMode = "WORKLOAD", WorkloadTotal, SubsystemsCount)
        ),
        _value: If(varSelectedSkylineMode = "WORKLOAD", ThisItem.WorkloadTotal, ThisItem.SubsystemsCount),
        _totalCount: Max(1, ThisItem.SubsystemsCount)
    },
    If(
