Set(varTasks_ReturnView, "Skyline");
Clear(colTasks);
Set(varTasks_Filter_Subsystem, varSelectedSkylineSubsystem.SubsystemCode);
Set(varOps_ToTasks_L3NodeId, "");
Set(varOps_ToTasks_L3DisplayName, "");
Set(varTasks_ContextSource, "Skyline");
Set(varApplySubsystemDefault, true);
Set(varTasks_Page, 1);
Set(varTasks_PageSize, 50);
Set(varTasks_AutoLoad, true);
Set(varAppView, "Tasks");
Navigate(scr_Tasks, ScreenTransition.None)

Set(varPunches_FilterSource, "Skyline");
Set(varPunches_ReturnView, "Skyline");
Set(varFilter_Subsystem, Coalesce(Text(varSelectedSkylineSubsystem.SubsystemCode), ""));
Set(varFilter_PunchTemplateId, Blank());
Set(varFilter_PunchCategoryCode, Blank());
Set(varFilter_PunchStatusCode, Blank());
Set(varFilter_PunchDiscipline, Blank());
Set(varFilter_Subcontractor, Blank());
Set(varPunches_Page, 1);
Set(varPunches_PageSize, 50);
Set(varPunches_HasSearched, true);
Set(varPunches_AutoLoad, true);
Clear(colPunches);
Set(varAppView, "Punches");
Navigate(scr_Punches, ScreenTransition.None)

Set(varSkylineLoading, true);
Set(varSkylineError, "");
Set(varSkylineLoaded, false);

Set(varGlobalLoading, true);
Set(varGlobalLoadingMsg, "Loading Delivery Skyline");
Set(varGlobalLoadingSubMsg, "Reading subsystem milestone forecast");
Set(varGlobalLoadingScope, "SKYLINE");

Clear(colSkylineRaw);
Clear(colSkylineWeeks);
Clear(colSkylineSelectedWeek);

If(
    IsBlank(varProjectId),
    Notify("Please select a project first.", NotificationType.Warning);
    Set(varSkylineLoading, false);
    Set(varGlobalLoading, false);
    Set(varGlobalLoadingMsg, "");
    Set(varGlobalLoadingSubMsg, "");
    Set(varGlobalLoadingScope, "");
    Exit()
);

IfError(
    With(
        {
            resp: Warroom_Pulse_GetSubsystemSkyline.Run(
                varProjectId,
                Text(varSkylineFromDate, "yyyy-mm-dd"),
                Text(varSkylineToDate, "yyyy-mm-dd"),
                varSkylinePunchWeight
            )
        },
        With(
            {
                arr: Table(ParseJSON(Coalesce(resp.result, "[]")))
            },
            ClearCollect(
                colSkylineRaw,
                ForAll(
                    arr,
                    With(
                        { r: ThisRecord.Value },
                        {
                            Id: Value(Text(r.Id)),
                            ProjectId: Value(Text(r.ProjectId)),
                            SubsystemCode: Text(r.SubsystemCode),
                            PlannedDate: If(IsBlank(Text(r.PlannedDate)) || Text(r.PlannedDate) = "null", Blank(), DateValue(Text(r.PlannedDate))),
                            ForecastDate: If(IsBlank(Text(r.ForecastDate)) || Text(r.ForecastDate) = "null", Blank(), DateValue(Text(r.ForecastDate))),
                            ActualDate: If(IsBlank(Text(r.ActualDate)) || Text(r.ActualDate) = "null", Blank(), DateValue(Text(r.ActualDate))),
                            SkylineDate: If(IsBlank(Text(r.SkylineDate)) || Text(r.SkylineDate) = "null", Blank(), DateValue(Text(r.SkylineDate))),
                            WeekEnding: If(IsBlank(Text(r.WeekEnding)) || Text(r.WeekEnding) = "null", Blank(), DateValue(Text(r.WeekEnding))),
                            OpenTasks: If(IsBlank(Text(r.OpenTasks)) || Text(r.OpenTasks) = "null", 0, Value(Text(r.OpenTasks))),
                            OpenPunches: If(IsBlank(Text(r.OpenPunches)) || Text(r.OpenPunches) = "null", 0, Value(Text(r.OpenPunches))),
                            WorkloadScore: If(IsBlank(Text(r.WorkloadScore)) || Text(r.WorkloadScore) = "null", 0, Value(Text(r.WorkloadScore))),
                            DaysRemaining: If(IsBlank(Text(r.DaysRemaining)) || Text(r.DaysRemaining) = "null", Blank(), Value(Text(r.DaysRemaining))),
                            RiskStatus: Text(r.RiskStatus),
                            ReadinessScore: If(IsBlank(Text(r.ReadinessScore)) || Text(r.ReadinessScore) = "null", 0, Value(Text(r.ReadinessScore))),
                            Notes: Text(r.Notes),
                            PunchWeight: If(IsBlank(Text(r.PunchWeight)) || Text(r.PunchWeight) = "null", varSkylinePunchWeight, Value(Text(r.PunchWeight)))
                        }
                    )
                )
            )
        )
    ),

    Set(varSkylineError, FirstError.Message);
    Notify("Error loading Skyline: " & varSkylineError, NotificationType.Error);
    Clear(colSkylineRaw)
);

ClearCollect(
    colSkylineWeeks,
    SortByColumns(
        AddColumns(
            GroupBy(
                Filter(colSkylineRaw, !IsBlank(WeekEnding)),
                WeekEnding,
                WeekItems
            ),
            SubsystemsCount,
            CountRows(WeekItems),
            OpenTasksTotal,
            Sum(WeekItems, OpenTasks),
            OpenPunchesTotal,
            Sum(WeekItems, OpenPunches),
            WorkloadTotal,
            Sum(WeekItems, WorkloadScore),
            CriticalCount,
            CountRows(Filter(WeekItems, RiskStatus = "Critical")),
            AtRiskCount,
            CountRows(Filter(WeekItems, RiskStatus = "At Risk")),
            OverdueCount,
            CountRows(Filter(WeekItems, RiskStatus = "Overdue")),
            OnTrackCount,
            CountRows(Filter(WeekItems, RiskStatus = "On Track")),
            AttentionCount,
            CountRows(Filter(WeekItems, RiskStatus = "Attention"))
        ),
        "WeekEnding",
        SortOrder.Ascending
    )
);

If(
    CountRows(colSkylineWeeks) > 0,
    Set(varSelectedSkylineWeek, First(colSkylineWeeks).WeekEnding);
    ClearCollect(
        colSkylineSelectedWeek,
        SortByColumns(
            Filter(colSkylineRaw, WeekEnding = varSelectedSkylineWeek),
            "WorkloadScore",
            SortOrder.Descending
        )
    ),
    Set(varSelectedSkylineWeek, Blank())
);

Set(varSkylineLastRefresh, Now());
Set(varSkylineLoaded, true);
Set(varSkylineLoading, false);

Set(varGlobalLoading, false);
Set(varGlobalLoadingMsg, "");
Set(varGlobalLoadingSubMsg, "");
Set(varGlobalLoadingScope, "");
